import {
  useI18n,
  Alert,
  Button,
  Checkbox,
  Field,
  FieldDescription,
  FieldError,
  FieldLabel,
  Input,
  Link,
  PasswordInput,
  Skeleton,
  cn,
} from '@gntik-ai/ui';
import { translatedContent } from '../../forms/translated-content';
import { Mail, User } from '@gntik-ai/icons';
import { useId, useState, type MouseEvent, type ReactNode } from 'react';
import { SsoButtons } from '../sso-buttons/SsoButtons';
import {
  AuthDivider,
  AuthHeader,
  EMAIL_RE,
  authFormClass,
  authSignUpFieldError,
  useAsyncSubmit,
  type AuthSignUpField,
  type AuthSignUpFieldLabels,
  type AuthUnavailableState,
  type AuthSignUpValidationMessages,
} from '../shared';
import { ValidationSummary, type ValidationIssue } from '../../forms/validation-summary/ValidationSummary';

export interface SignUpValues {
  name: string;
  email: string;
  password: string;
  /** Present only in configured mode. Text/email values are trimmed and keyed by field id. */
  fields?: Record<string, string>;
}

export interface SignUpFormLabels extends AuthSignUpFieldLabels {
  eyebrow: string;
  title: string;
  description: string;
  name: string;
  namePlaceholder: string;
  nameRequired: string;
  email: string;
  emailPlaceholder: string;
  password: string;
  passwordTooShort: (minimum: number) => string;
  termsRequired: string;
  terms: string;
  privacy: string;
  termsConsent: (terms: ReactNode, privacy: ReactNode) => ReactNode;
  submit: string;
  divider: string;
  signInPrompt: string;
  signIn: string;
  policyLoading: string;
  fallbackError: string;
  emailInvalid: string;
}

export interface SignUpFormProps {
  labels?: Partial<SignUpFormLabels>;
  /** Ordered text/email inputs before Password. Omit to keep the default fields and payload. */
  fields?: readonly AuthSignUpField[];
  messages?: AuthSignUpValidationMessages;
  /** Replaces all account creation controls with a consumer-supplied callout. */
  unavailable?: AuthUnavailableState;
  /** Resolving policy, separate from loading (an account submission). No form is rendered. */
  policyLoading?: boolean;
  /** Creates the account. A returned promise shows the loading state; a rejection shows in the alert. */
  onSubmit?: (values: SignUpValues) => void | Promise<void>;
  error?: string | null;
  loading?: boolean;
  /** Optional password guidance; receives the current minimum length when a function is supplied. */
  passwordHelp?: ReactNode | ((minimum: number) => ReactNode);
  /** Minimum password length. Defaults to 8. */
  minPasswordLength?: number;
  /** Omit to require consent; false removes the checkbox and consent validation. */
  terms?: false;
  termsHref?: string;
  privacyHref?: string;
  signInHref?: string;
  onSignIn?: () => void;
  /** SSO area under the divider; defaults to SsoButtons, `null` hides it. */
  sso?: ReactNode;
  eyebrow?: ReactNode;
  title?: ReactNode;
  description?: ReactNode;
  className?: string;
}

/** Account creation: name, work email, password with a strength meter and a required terms checkbox. */
export function SignUpForm({
  labels,
  fields,
  messages,
  unavailable,
  policyLoading = false,
  onSubmit,
  error: errorProp,
  loading: loadingProp,
  minPasswordLength = 8,
  passwordHelp,
  terms: termsProp,
  termsHref = '#',
  privacyHref = '#',
  signInHref = '#',
  onSignIn,
  sso = <SsoButtons />,
  eyebrow: eyebrowProp,
  title: titleProp,
  description: descriptionProp,
  className,
}: SignUpFormProps) {
  const { t } = useI18n();
  const eyebrow = eyebrowProp === undefined ? (labels?.eyebrow ?? t('signUp.eyebrow')) : eyebrowProp;
  const title = titleProp === undefined ? (labels?.title ?? t('signUp.title')) : titleProp;
  const description =
    descriptionProp === undefined ? (labels?.description ?? t('signUp.description')) : descriptionProp;
  const termsErrorId = useId();
  const fieldPrefix = useId();
  const passwordId = `${fieldPrefix}-password`;
  const termsId = `${fieldPrefix}-terms`;
  const [fieldValues, setFieldValues] = useState<Record<string, string>>({});
  const [submitCount, setSubmitCount] = useState(0);
  const fieldValue = (id: string) => (Object.hasOwn(fieldValues, id) ? (fieldValues[id] ?? '') : '');
  const configuredErrors: ValidationIssue[] = (fields ?? []).flatMap((field) => {
    const message = authSignUpFieldError(fieldValue(field.id), field, t, labels);
    return message ? [{ fieldId: `${fieldPrefix}-field-${field.id}`, label: field.label, message }] : [];
  });
  const [name, setName] = useState('');
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [terms, setTerms] = useState(false);
  const [submitted, setSubmitted] = useState(false);
  const { loading, error, run } = useAsyncSubmit(labels?.fallbackError ?? t('signUp.fallbackError'));
  const busy = loadingProp ?? loading;
  const alert = errorProp ?? error;
  const nameInvalid = submitted && name.trim() === '';
  const emailInvalid = submitted && !EMAIL_RE.test(email.trim());
  const passwordInvalid =
    (submitted || (fields !== undefined && password.length > 0)) && password.length < minPasswordLength;
  const termsInvalid = submitted && termsProp !== false && !terms;

  const passwordError =
    messages?.passwordTooShort?.(minPasswordLength) ??
    labels?.passwordTooShort?.(minPasswordLength) ??
    t('signUp.passwordTooShort', { minimum: minPasswordLength });
  const termsError = messages?.termsRequired ?? labels?.termsRequired ?? t('signUp.termsRequired');
  const termsLink = <Link href={termsHref}>{labels?.terms ?? t('signUp.terms')}</Link>;
  const privacyLink = <Link href={privacyHref}>{labels?.privacy ?? t('signUp.privacy')}</Link>;
  const summaryErrors = [
    ...configuredErrors,
    ...(password.length < minPasswordLength
      ? [{ fieldId: passwordId, label: labels?.password ?? t('signUp.password'), message: passwordError }]
      : []),
    ...(termsProp !== false && !terms
      ? [{ fieldId: termsId, label: labels?.terms ?? t('signUp.terms'), message: termsError }]
      : []),
  ];

  if (unavailable)
    return (
      <div className={cn(authFormClass, className)}>
        <Alert tone="info" title={unavailable.title} description={unavailable.message} actions={unavailable.action} />
      </div>
    );

  if (policyLoading)
    return (
      <div className={cn(authFormClass, 'flex flex-col gap-4', className)}>
        <span role="status" className="sr-only">
          {labels?.policyLoading ?? t('signUp.policyLoading')}
        </span>
        <Skeleton aria-hidden className="h-8 w-3/4" />
        <Skeleton aria-hidden className="h-4 w-full" />
        <Skeleton aria-hidden className="h-12 w-full" />
        <Skeleton aria-hidden className="h-12 w-full" />
        <Skeleton aria-hidden className="h-12 w-full" />
      </div>
    );

  return (
    <div className={cn(authFormClass, className)}>
      <AuthHeader eyebrow={eyebrow} title={title} description={description} />
      <form
        noValidate
        aria-label={labels?.submit ?? t('signUp.submit')}
        className="flex flex-col gap-4"
        onSubmit={(e) => {
          e.preventDefault();
          setSubmitted(true);
          if (fields !== undefined) {
            setSubmitCount((count) => count + 1);
            if (summaryErrors.length > 0) return;
            const values = Object.fromEntries(fields.map((field) => [field.id, fieldValue(field.id).trim()]));
            void run(() =>
              onSubmit?.({ name: values.name ?? '', email: values.email ?? '', password, fields: values }),
            );
            return;
          }
          if (
            name.trim() === '' ||
            !EMAIL_RE.test(email.trim()) ||
            password.length < minPasswordLength ||
            (termsProp !== false && !terms)
          )
            return;
          void run(() => onSubmit?.({ name: name.trim(), email: email.trim(), password }));
        }}
      >
        {alert && <Alert tone="destructive" description={alert} />}
        {fields !== undefined && submitted && (
          // Destructive text needs an untinted surface to meet contrast in the light theme.
          <ValidationSummary errors={summaryErrors} submitCount={submitCount} className="bg-background" />
        )}
        {fields !== undefined ? (
          fields.map((field) => {
            const message = authSignUpFieldError(fieldValue(field.id), field, t, labels);
            const invalid = submitted && message !== null;
            return (
              <Field key={field.id} invalid={invalid}>
                <FieldLabel>{field.label}</FieldLabel>
                <Input
                  id={`${fieldPrefix}-field-${field.id}`}
                  type={field.type ?? 'text'}
                  autoComplete={field.autoComplete}
                  placeholder={field.placeholder}
                  required={field.required}
                  value={fieldValue(field.id)}
                  onValueChange={(value) => setFieldValues((values) => ({ ...values, [field.id]: value }))}
                />
                {field.help != null && <FieldDescription>{field.help}</FieldDescription>}
                <FieldError match={invalid}>{message}</FieldError>
              </Field>
            );
          })
        ) : (
          <>
            <Field invalid={nameInvalid}>
              <FieldLabel>{labels?.name ?? t('signUp.name')}</FieldLabel>
              <Input
                leadingIcon={User}
                autoComplete="name"
                placeholder={labels?.namePlaceholder ?? t('signUp.namePlaceholder')}
                value={name}
                onValueChange={setName}
                required
              />
              <FieldError match={nameInvalid}>{labels?.nameRequired ?? t('signUp.nameRequired')}</FieldError>
            </Field>
            <Field invalid={emailInvalid}>
              <FieldLabel>{labels?.email ?? t('signUp.email')}</FieldLabel>
              <Input
                type="email"
                leadingIcon={Mail}
                autoComplete="email"
                placeholder={labels?.emailPlaceholder ?? t('signUp.emailPlaceholder')}
                value={email}
                onValueChange={setEmail}
                required
              />
              <FieldError match={emailInvalid}>{labels?.emailInvalid ?? t('authValidation.emailInvalid')}</FieldError>
            </Field>
          </>
        )}
        <Field invalid={passwordInvalid}>
          <FieldLabel>{labels?.password ?? t('signUp.password')}</FieldLabel>
          <PasswordInput
            id={fields !== undefined ? passwordId : undefined}
            showStrength
            strength={password.length > 0 && password.length < minPasswordLength ? 0 : undefined}
            value={password}
            onValueChange={setPassword}
            required
          />
          {passwordHelp != null && (
            <FieldDescription>
              {typeof passwordHelp === 'function' ? passwordHelp(minPasswordLength) : passwordHelp}
            </FieldDescription>
          )}
          <FieldError match={passwordInvalid}>{passwordError}</FieldError>
        </Field>
        {termsProp !== false && (
          <div>
            <Checkbox
              render={fields !== undefined ? <span id={termsId} /> : undefined}
              checked={terms}
              onCheckedChange={setTerms}
              aria-invalid={termsInvalid || undefined}
              aria-describedby={termsInvalid ? termsErrorId : undefined}
              label={
                labels?.termsConsent?.(termsLink, privacyLink) ??
                translatedContent(t('signUp.termsConsent'), { terms: termsLink, privacy: privacyLink })
              }
            />
            {termsInvalid && (
              <p id={termsErrorId} className="mt-1.5 text-[12.5px] text-destructive-text">
                {termsError}
              </p>
            )}
          </div>
        )}
        <Button type="submit" size="lg" loading={busy} className="mt-2 w-full">
          {labels?.submit ?? t('signUp.submit')}
        </Button>
      </form>
      {sso != null && (
        <>
          <AuthDivider>{labels?.divider ?? t('signUp.divider')}</AuthDivider>
          {sso}
        </>
      )}
      <p className="mt-7 text-center text-[13px] text-muted-foreground">
        {labels?.signInPrompt ?? t('signUp.signInPrompt')}{' '}
        <Link
          href={signInHref}
          onClick={
            onSignIn
              ? (e: MouseEvent) => {
                  e.preventDefault();
                  onSignIn();
                }
              : undefined
          }
        >
          {labels?.signIn ?? t('signUp.signIn')}
        </Link>
      </p>
    </div>
  );
}

import { cn, en, useI18n, type I18n } from '@gntik-ai/ui';
import { useState, type ReactNode } from 'react';

export interface AuthHeaderProps {
  eyebrow?: ReactNode;
  title: ReactNode;
  description?: ReactNode;
  /** Defaults to h1. `null` omits the title heading. */
  headingLevel?: 'h1' | 'h2' | 'h3' | null;
  className?: string;
}

/** Eyebrow + title + supporting line used at the top of every auth form. */
export function AuthHeader({ eyebrow, title, description, headingLevel: Heading = 'h1', className }: AuthHeaderProps) {
  return (
    <div className={cn('mb-6', className)}>
      {eyebrow != null && (
        <p className="mb-2.5 font-mono text-[11px] tracking-[0.2em] text-primary-text uppercase">{eyebrow}</p>
      )}
      {Heading != null && title != null && (
        <Heading className="text-[24px] font-semibold tracking-tight text-balance text-foreground sm:text-[27px]">
          {title}
        </Heading>
      )}
      {description != null && (
        <p className="mt-2 text-[14px] leading-relaxed text-pretty text-muted-foreground">{description}</p>
      )}
    </div>
  );
}

/** Horizontal rule with a centred caption ("Or continue with"). */
export function AuthDivider({ children }: { children: ReactNode }) {
  return (
    <div className="my-6 flex items-center gap-3" role="presentation">
      <span className="h-px flex-1 bg-border" />
      <span className="font-mono text-[10.5px] font-semibold tracking-[0.2em] text-muted-foreground uppercase">
        {children}
      </span>
      <span className="h-px flex-1 bg-border" />
    </div>
  );
}

export const authFormClass = 'w-full max-w-[392px]';

/** Loading + error state around an async submit handler. A rejection's message becomes the error. */
export function useAsyncSubmit(fallbackError?: string) {
  const { t } = useI18n();
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const run = async (fn: () => void | Promise<void>) => {
    setError(null);
    setLoading(true);
    try {
      await fn();
      setLoading(false);
      return true;
    } catch (e) {
      setLoading(false);
      setError(e instanceof Error ? e.message : (fallbackError ?? t('authValidation.fallbackError')));
      return false;
    }
  };
  return { loading, error, setError, run };
}

export const EMAIL_RE = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

/** Email by default; text mode supports a username or username-or-email identifier. */
export interface AuthIdentifierConfig {
  type?: 'email' | 'text';
  autoComplete?: string;
  label?: ReactNode;
  help?: ReactNode;
  /** Optional stable id for the FieldDescription. Otherwise Base UI generates it. */
  helpId?: string;
  placeholder?: string;
  minLength?: number;
  maxLength?: number;
}

/** Kit-owned inline validation; consumers supply copy rather than running a second validator. */
export interface AuthValidationMessages {
  identifierRequired?: string;
  identifierInvalid?: string;
  identifierTooShort?: string;
  passwordRequired?: string;
}

/** Server errors use only these props plus the form's error alert; inline validation stays in the kit. */
export interface AuthFormAccessibilityProps {
  fieldInvalid?: { identifier?: boolean; password?: boolean };
  /** Id of the server alert (or an external feedback element), appended to flagged inputs. */
  feedbackId?: string;
  /** Describes the form itself; does not replace the per-field feedback association. */
  'aria-describedby'?: string;
  'aria-label'?: string;
  'aria-labelledby'?: string;
}

export function authIdentifierError(
  value: string,
  config?: AuthIdentifierConfig,
  messages?: AuthValidationMessages,
  t?: I18n['t'],
  labels?: AuthValidationMessages,
) {
  const trimmed = value.trim();
  const fallback =
    config?.type === 'text'
      ? (t?.('authValidation.identifierInvalid') ?? en['authValidation.identifierInvalid'])
      : (t?.('authValidation.emailInvalid') ?? en['authValidation.emailInvalid']);
  if (!trimmed) return messages?.identifierRequired ?? labels?.identifierRequired ?? fallback;
  if (config?.minLength !== undefined && trimmed.length < config.minLength)
    return (
      messages?.identifierTooShort ??
      messages?.identifierInvalid ??
      labels?.identifierTooShort ??
      labels?.identifierInvalid ??
      fallback
    );
  if (
    ((config?.type ?? 'email') === 'email' && !EMAIL_RE.test(trimmed)) ||
    (config?.maxLength !== undefined && trimmed.length > config.maxLength)
  )
    return messages?.identifierInvalid ?? labels?.identifierInvalid ?? fallback;
  return null;
}

/** Ordered text/email fields collected before the sign-up password. Ids must be unique. */
export interface AuthSignUpField {
  id: string;
  label: string;
  placeholder?: string;
  help?: ReactNode;
  required?: boolean;
  type?: 'text' | 'email';
  autoComplete?: string;
  /** Consumer copy for kit-owned validation. */
  messages?: { required?: string; invalid?: string };
}

export interface AuthSignUpFieldLabels {
  fieldRequired: (label: string) => string;
  fieldInvalid: string;
}

export function authSignUpFieldError(
  value: string,
  field: AuthSignUpField,
  t?: I18n['t'],
  labels?: Partial<AuthSignUpFieldLabels>,
) {
  const trimmed = value.trim();
  if (!trimmed)
    return field.required
      ? (field.messages?.required ??
          labels?.fieldRequired?.(field.label) ??
          t?.('authValidation.fieldRequired', { label: field.label }) ??
          en['authValidation.fieldRequired'].replace('{label}', () => field.label))
      : null;
  if (field.type === 'email' && !EMAIL_RE.test(trimmed))
    return (
      field.messages?.invalid ??
      labels?.fieldInvalid ??
      t?.('authValidation.emailInvalid') ??
      en['authValidation.emailInvalid']
    );
  return null;
}

/** Consumer-owned copy and optional action when account creation is unavailable. */
export interface AuthUnavailableState {
  title: ReactNode;
  message: ReactNode;
  action?: ReactNode;
}

/** Kit-owned sign-up validation with consumer-owned copy. */
export interface AuthSignUpValidationMessages {
  passwordTooShort?: (minimum: number) => string;
  termsRequired?: string;
}

import { Fragment, type ReactNode } from 'react';

/** Keep caller-owned rich content in place while the catalog controls sentence order. */
export function translatedContent(message: string, values: Record<string, ReactNode>): ReactNode {
  return message
    .split(/(\{\w+\})/)
    .map((part, index) => (
      <Fragment key={index}>
        {part.startsWith('{') && part.endsWith('}') ? (values[part.slice(1, -1)] ?? part) : part}
      </Fragment>
    ));
}
